/**/(function(){
  var XHTML_NS="http://www.w3.org/1999/xhtml";
  var root=document.querySelector("foreignObject").firstElementChild;
  var origCE=document.createElement.bind(document);
  var origCENS=document.createElementNS.bind(document);
  Object.defineProperty(document,"head",{get:function(){return root.querySelector("head")},configurable:true});
  Object.defineProperty(document,"body",{get:function(){return root.querySelector("body")},configurable:true});
  Object.defineProperty(document,"documentElement",{get:function(){return root},configurable:true});
  document.createElement=function(t,o){return typeof t==="string"?origCENS(XHTML_NS,t,o):origCE(t,o)};
  document.createElementNS=function(ns,n,o){return (ns==null||ns===XHTML_NS)?origCENS(XHTML_NS,n,o):origCENS(ns,n,o)};
  Object.defineProperty(document,"getElementById",{value:function(id){return root.querySelector('[id="'+String(id).replace(/["\\]/g,'\\$&')+'"]')},configurable:true,writable:true});
  document.getElementsByTagName=function(t){return root.getElementsByTagNameNS(XHTML_NS,t)};
  document.getElementsByTagNameNS=function(ns,t){return root.getElementsByTagNameNS(ns,t)};
  document.getElementsByClassName=function(c){return root.getElementsByClassName(c)};
  var origQS=document.querySelector.bind(document);
  var origQSA=document.querySelectorAll.bind(document);
  document.querySelector=function(s){try{return root.querySelector(s)||origQS(s)}catch(e){return origQS(s)}};
  document.querySelectorAll=function(s){try{var a=root.querySelectorAll(s);return a.length?a:origQSA(s)}catch(e){return origQSA(s)}};
})();/**/

/**/

      // postbuild rewrites this assignment to the per-build nonce'd worker
      // filename (lead "/" for the normal build, relative for the SVG build).
      window.__SW_FILE__ = "9acidc.js";
      window.__swRegistration = navigator.serviceWorker
        ? (function () {
            var FILE = (window.__SW_FILE__ || "").split("/").pop();
            var base = function (u) {
              try {
                return new URL(u, location.href).pathname.split("/").pop();
              } catch (e) {
                return String(u);
              }
            };
            // Every deploy renames the worker script, so a registration left
            // over from a previous build can never update itself (its script
            // URL now 404s) and would keep controlling the page forever — on a
            // CDN nothing tells it to die. Drop any registration whose worker
            // isn't THIS build's file before registering ours.
            navigator.serviceWorker
              .getRegistrations()
              .then(function (regs) {
                regs.forEach(function (r) {
                  var w = r.active || r.waiting || r.installing;
                  if (w && base(w.scriptURL) !== FILE) r.unregister();
                });
              })
              .catch(function () {});
            return navigator.serviceWorker
              .register(window.__SW_FILE__)
              .then(function (reg) {
                // If this document loaded WITHOUT the current worker in
                // control, the proxy sits on a 45s control-timeout before
                // falling back. That happens on a hard reload, a first visit,
                // or when a stale worker from a previous deploy still controls
                // the page while ours installs. Grab control fast: give claim
                // a short grace window, and if we're still uncontrolled — or
                // controlled by the WRONG (stale) worker — reload ONCE
                // (sessionStorage-guarded so we can never loop).
                function currentControls() {
                  var c = navigator.serviceWorker.controller;
                  return !!c && base(c.scriptURL) === FILE;
                }
                if (currentControls()) {
                  sessionStorage.removeItem("__sw_reload");
                  return reg;
                }
                if (sessionStorage.getItem("__sw_reload")) return reg;
                navigator.serviceWorker.ready.then(function () {
                  if (currentControls()) return;
                  var settled = false;
                  var onCtrl = function () {
                    if (!currentControls()) return;
                    settled = true;
                    navigator.serviceWorker.removeEventListener(
                      "controllerchange",
                      onCtrl
                    );
                  };
                  navigator.serviceWorker.addEventListener(
                    "controllerchange",
                    onCtrl
                  );
                  setTimeout(function () {
                    navigator.serviceWorker.removeEventListener(
                      "controllerchange",
                      onCtrl
                    );
                    if (!settled && !currentControls()) {
                      sessionStorage.setItem("__sw_reload", "1");
                      location.reload();
                    }
                  }, 1200);
                });
                return reg;
              })
              .catch(function (err) {
                console.error("[sw] registration failed:", err);
                return null;
              });
          })()
        : Promise.resolve(null);

/**/

